tool_input.command:
cat > test-debug.ts << 'EOF'
import { TestApp } from '@guren/testing'
import { createApiToken } from '@guren/core'
import app from './src/app.js'
import { User } from './app/Models/User.js'
import { apiTokenStore } from './routes/mcp.js'

const http = await TestApp.fromApp(app)

const user = await User.create({
  name: 'Test User',
  email: `mcp-debug-${Date.now()}@example.com`,
  password: 'password123',
})

const { token: plainToken } = await createApiToken(apiTokenStore, {
  userId: user.id,
  abilities: [],
})

const res = await http
  .withHeader('Authorization', `Bearer ${plainToken}`)
  .post('/mcp', {
    jsonrpc: '2.0',
    method: 'tools/call',
    params: {
      name: 'posts_search',
      arguments: {
        keywords: ['test'],
        limit: 10,
      },
    },
    id: '2',
  })

console.log('Status:', res.status)
const data = await res.json()
console.log('Response:', JSON.stringify(data, null, 2))
EOF
bun test-debug.ts 2>&1
